INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(51606429, 'The Phantom Knights of Tomb Shield', '幻影骑士团 墓盾', '幻影騎士団トゥーム・シールド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这张卡发动后变成通常怪兽（战士族·暗·3星·攻/守0）在怪兽区域攻击表示特殊召唤（不当作陷阱卡使用）。 ②：自己回合把墓地的这张卡除外，以对方场上1张表侧表示的陷阱卡为对象才能发动。那张卡的效果直到回合结束时无效。这个效果在这张卡送去墓地的回合不能发动。'),
(25538345, 'The Phantom Knights of Torn Scales', '魅影骑士团裂鳞甲', '幻影騎士団ティアースケイル', 'Effect Monster', 'Warrior', 'DARK', 3, 600, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。除「幻影骑士团 破洞鳞甲」外的1只「幻影骑士团」怪兽或1张「幻影」魔法·陷阱卡从卡组送去墓地。 ②：这张卡在墓地存在，从自己墓地有其他的「幻影骑士团」怪兽或「幻影」魔法·陷阱卡被除外的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(62645025, 'The Phantom Knights of Wrong Magnetring', '幻影骑士团 失常磁环', '幻影騎士団ウロング・マグネリング', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。那次攻击无效。那之后，这张卡变成持有以下效果的效果怪兽（战士族·暗·2星·攻/守0）在怪兽区域攻击表示特殊召唤（不当作陷阱卡使用）。 ●把这张卡以及自己场上的表侧表示的1只「幻影骑士团」怪兽或者1张「幻影」永续魔法·永续陷阱卡送去墓地才能发动。自己从卡组抽2张。这个效果在对方回合也能发动。'),
(3298689, 'The Phantom Knights'' Rank-Up-Magic Launch', '升阶魔法－魅影骑士团出击', 'RUM－幻影騎士団ラウンチ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己·对方的主要阶段，以自己场上1只没有超量素材的暗属性超量怪兽为对象才能发动。比那只自己怪兽阶级高1阶的1只暗属性超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤，把这张卡在下面重叠作为超量素材。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只暗属性超量怪兽为对象才能发动。把手卡1只「幻影骑士团」怪兽在那只怪兽下面重叠作为超量素材。'),
(32541773, 'The Portrait''s Secret', '绘画中的潜藏者', '絵画に潜む者', 'Normal Monster', 'Fiend', 'EARTH', 4, 1200, 1500, '寄宿着作者的诅咒的画，据说持有它的人都将陷入不幸之中。'),
(54241725, 'The Prime Monarch', '真源的帝王', '真源の帝王', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「真源的帝王」的②的效果1回合只能使用1次。 ①：1回合1次，以自己墓地2张「帝王」魔法·陷阱卡为对象才能发动。那些卡加入卡组洗切。那之后，自己从卡组抽1张。 ②：这张卡在墓地存在的场合，把这张卡以外的自己墓地1张「帝王」魔法·陷阱卡除外才能发动。这张卡变成通常怪兽（天使族·光·5星·攻1000/守2400）在怪兽区域守备表示特殊召唤（不当作陷阱卡使用）。'),
(300302019, 'The Psychic Duelist', NULL, NULL, 'Skill Card', 'Espa Roba', NULL, NULL, NULL, NULL, NULL),
(40703393, 'The Puppet Magic of Dark Ruler', '冥界流傀儡术', '冥界流傀儡術', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地的1只恶魔族怪兽。在自己场上选择合计等级和选择的那只怪兽的等级相同的怪兽从游戏中除外。之后，选择的那只怪兽特殊召唤。'),
(296499, 'The Regulation of Tribe', '一族之规', '一族の掟', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '发动时宣言1个种族。那个种族的怪兽不能攻击宣言。每次自己的准备阶段若不把1只怪兽作为祭品这张卡破坏。'),
(16430187, 'The Reliable Guardian', '可靠的守护者', '頼もしき守護者', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '场上表侧表示存在的1只怪兽的守备力直到结束阶段时上升700。'),
(59371387, 'The Resolute Meklord Army', '铁壁机皇兵', '鉄壁の機皇兵', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己场上表侧攻击表示存在的名字带有「机皇兵」的怪兽的效果无效化，不会被战斗破坏。'),
(56001930, 'The Return to the Normal', '怪蹴一色', '怪蹴一色', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：只让怪兽1只召唤·特殊召唤时才能发动。持有比那只怪兽低的攻击力的场上的怪兽全部破坏。'),
(17509503, 'The Revenge of the Normal', '一色即发', '一色即発', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把最多有对方场上的怪兽数量的4星以下的怪兽从手卡特殊召唤。'),
(59094601, 'The Revived Sky God', '苏生的天空神', '蘇りし天空神', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，那些发动和效果不会被无效化。 ①：从自己墓地选1只「奥西里斯之天空龙」特殊召唤。那之后，双方各自直到手卡变成6张为止从卡组抽卡。 ②：把墓地的这张卡除外才能发动。从自己的卡组·墓地选1张「死者苏生」在卡组最上面放置。自己墓地有幻神兽族怪兽存在的场合，再让自己从卡组抽1张。'),
(300302041, 'The Right Hero for the Job', NULL, NULL, 'Skill Card', 'Jaden Yuki', NULL, NULL, NULL, NULL, NULL),
(76305638, 'The Rock Spirit', '岩之精灵 泰坦', '岩の精霊 タイタン', 'Effect Monster', 'Rock', 'EARTH', 4, 1700, 1000, '这张卡不能通常召唤。自己墓地1只地属性怪兽从游戏中除外特殊召唤上场。这只怪兽在对方的战斗阶段攻击力上升300。'),
(300302054, 'The Roids are Alright', NULL, NULL, 'Skill Card', 'Syrus Truesda', NULL, NULL, NULL, NULL, NULL),
(17269895, 'The Ruler''s Rumbling', NULL, NULL, 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(26684111, 'The Sacred Waters in the Sky', '天空的圣水', '天空の聖水', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1张「天空的圣域」发动或把有「天空的圣域」的卡名记述的1只怪兽加入手卡。那之后，场上或者墓地有「天空的圣域」存在的场合，自己可以回复自己场上的「许珀里翁」怪兽以及「代行者」怪兽数量×500基本分。 ②：有「天空的圣域」的卡名记述的自己怪兽被战斗破坏的场合，可以作为代替把墓地的这张卡除外。'),
(48152161, 'The Sanctified Darklord', '神属的堕天使', '神属の堕天使', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡以及自己场上的表侧表示怪兽之中把1只「堕天使」怪兽送去墓地才能发动。选场上1只效果怪兽，那个效果直到回合结束时无效，自己基本分回复那只怪兽的攻击力的数值。'),
(56433456, 'The Sanctuary in the Sky', '天空的圣域', '天空の聖域', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，天使族怪兽的战斗发生的对那控制者的战斗伤害变成0。'),
(15449853, 'The Sanctum of Parshath', '珀耳修斯的神域', 'パーシアスの神域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡的卡名只要在场上·墓地存在当作「天空的圣域」使用。 ②：只要这张卡在魔法与陷阱区域存在，场上的天使族怪兽的攻击力·守备力上升300，场上盖放的魔法·陷阱卡不会成为效果的对象，不会被效果破坏。 ③：1回合1次，从自己墓地的天使族怪兽以及反击陷阱卡之中以合计3张为对象才能发动（同名卡最多1张）。那些卡用喜欢的顺序回到卡组上面。'),
(48179391, 'The Seal of Orichalcos', '奥利哈刚的结界', 'オレイカルコスの結界', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在决斗中只能发动1张。 ①：作为这张卡的发动时的效果处理，自己场上有特殊召唤的怪兽存在的场合，那些怪兽全部破坏。 ②：自己不能从额外卡组把怪兽特殊召唤。 ③：自己场上的怪兽的攻击力上升500。 ④：自己场上有表侧攻击表示怪兽2只以上存在的场合，对方不能选择自己场上的攻击力最低的怪兽作为攻击对象。 ⑤：这张卡1回合只有1次不会被效果破坏。'),
(4081094, 'The Second Sarcophagus', '第二之棺', '第二の棺', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡只能通过「第一之棺」的效果上场。'),
(99351431, 'The Secret of the Bandit', '盗贼的极意', '盗賊の極意', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '只能在主要阶段一发动。选择场上的1只表侧表示存在的怪兽。在这个回合，选择的怪兽每次给与对方玩家战斗伤害，对方随机丢弃1张手卡。'),
(30888983, 'The Selection', '方舟之选别', '方舟の選別', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己或者对方把怪兽召唤·反转召唤·特殊召唤之际支付1000基本分才能发动。场上有相同种族的怪兽存在的怪兽的召唤·反转召唤·特殊召唤无效，那些怪兽破坏。'),
(63125616, 'The Shadow Who Controls the Dark', '司暗的影子', '闇を司る影', 'Normal Monster', 'Fiend', 'DARK', 3, 800, 700, '溶入黑暗之中的影子。用金网封住对方的行动。'),
(43434803, 'The Shallow Grave', '过浅的墓穴', '浅すぎた墓穴', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '双方玩家选择各自墓地1只怪兽在各自场上里侧守备表示盖放。'),
(27782503, 'The Six Samurai - Irou', '六武众-伊郎', '六武衆－イロウ', 'Effect Monster', 'Warrior', 'DARK', 4, 1700, 1200, '自己场上有「六武众-伊郎」以外的名字带有「六武众」的怪兽存在，这张卡向里侧守备表示怪兽攻击的场合，不进行伤害计算以里侧守备表示的状态把那只怪兽破坏。此外，场上表侧表示存在的这张卡被破坏的场合，可以作为代替把这张卡以外的自己场上表侧表示存在的1只名字带有「六武众」的怪兽破坏。'),
(90397998, 'The Six Samurai - Kamon', '六武众-火门', '六武衆－カモン', 'Effect Monster', 'Warrior', 'FIRE', 3, 1500, 1000, '自己场上有「六武众-火门」以外的名字带有「六武众」的怪兽存在的场合，1回合1次，可以选择场上表侧表示存在的1张魔法·陷阱卡破坏。这个效果发动的回合，这张卡不能攻击宣言。此外，场上表侧表示存在的这张卡被破坏的场合，可以作为代替把这张卡以外的自己场上表侧表示存在的1只名字带有「六武众」的怪兽破坏。'),
(31904181, 'The Six Samurai - Nisashi', '六武众-二藏', '六武衆－ニサシ', 'Effect Monster', 'Warrior', 'WIND', 4, 1400, 700, '自己场上有「六武众-二藏」以外的名字带有「六武众」的怪兽存在的场合，这张卡在同1次的战斗阶段中可以作2次攻击。此外，场上表侧表示存在的这张卡被破坏的场合，可以作为代替把这张卡以外的自己场上表侧表示存在的1只名字带有「六武众」的怪兽破坏。'),
(64398890, 'The Six Samurai - Yaichi', '六武众-矢一', '六武衆－ヤイチ', 'Effect Monster', 'Warrior', 'WATER', 3, 1300, 800, '自己场上有「六武众-矢一」以外的名字带有「六武众」的怪兽存在的场合，1回合1次，可以选择场上盖放的1张魔法·陷阱卡破坏。这个效果发动的回合，这张卡不能攻击宣言。此外，场上表侧表示存在的这张卡被破坏的场合，可以作为代替把这张卡以外的自己场上表侧表示存在的1只名字带有「六武众」的怪兽破坏。'),
(69025477, 'The Six Samurai - Yariza', '六武众-枪左', '六武衆－ヤリザ', 'Effect Monster', 'Warrior', 'EARTH', 3, 1000, 500, '自己场上有「六武众-枪左」以外的名字带有「六武众」的怪兽存在的场合，这张卡可以直接攻击对方玩家。此外，场上表侧表示存在的这张卡被破坏的场合，可以作为代替把这张卡以外的自己场上表侧表示存在的1只名字带有「六武众」的怪兽破坏。'),
(95519486, 'The Six Samurai - Zanji', '六武众-斩次', '六武衆－ザンジ', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 1300, '自己场上有「六武众-斩次」以外的名字带有「六武众」的怪兽存在的场合，这张卡攻击的怪兽在伤害步骤结束时破坏。此外，场上表侧表示存在的这张卡被破坏的场合，可以作为代替把这张卡以外的自己场上表侧表示存在的1只名字带有「六武众」的怪兽破坏。'),
(6357341, 'The Six Shinobi', '忍之六武', '忍の六武', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「六武众」怪兽6只存在，那些属性全部不同的场合才能发动。下次的对方回合跳过。'),
(29491031, 'The Snake Hair', '美杜莎的亡灵', 'メデューサの亡霊', 'Normal Monster', 'Zombie', 'DARK', 4, 1500, 1200, '头发满是毒蛇的怪兽。一旦被她的目光盯上，就会被石化。'),
(99517131, 'The Spell Absorbing Life', '生命力吸收魔术', '生命力吸収魔術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '将场上所有里侧守备表示的怪兽全部变成表侧表示。此时反转效果不发动。之后场上每存在1只效果怪兽，自己回复400基本分。'),
(15123983, 'THE Star Ham', '星鼠侠', 'THE・スターハム', 'Synchro Monster', 'Beast', 'LIGHT', 3, 1000, 1200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，丢弃1张手卡才能发动。那1只作为同调素材的怪兽从自己墓地特殊召唤。这个效果特殊召唤的怪兽当作调整使用。 ②：这张卡在墓地存在的场合，丢弃2张手卡才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(10262698, 'The Statue of Easter Island', '复活节岛石像', 'イースター島のモアイ', 'Normal Monster', 'Rock', 'EARTH', 4, 1100, 1400, '存在于复活岛的石像，能够发射圆形的激光。'),
(87557188, 'The Stern Mystic', '严格的老魔术师', '厳格な老魔術師', 'Flip Effect Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1200, '①：这张卡反转的场合发动。场上盖放的卡全部确认。'),
(24413299, 'The Suppression Pluto', '镇压冥王星', 'The suppression PLUTO', 'Effect Monster', 'Fiend', 'DARK', 8, 2600, 2000, '①：1回合1次，宣言1个卡名才能发动。对方手卡全部确认，那之中有宣言的卡的场合，从以下效果选1个适用。 ●选对方场上1只怪兽得到控制权。 ●选对方场上1张魔法·陷阱卡破坏。那之后，可以把破坏的那张魔法·陷阱卡在自己场上盖放。'),
(51402908, 'The Supremacy Sun', '至尊太阳', 'The supremacy SUN', 'Effect Monster', 'Fiend', 'DARK', 10, 3000, 3000, '这张卡不用这张卡的效果不能特殊召唤。场上表侧表示存在的这张卡被破坏送去墓地的场合，下个回合的准备阶段时，可以丢弃1张手卡，这张卡从墓地特殊召唤。'),
(44771289, 'The Terminus of the Burning Abyss', '旅人的结彼岸', '旅人の結彼岸', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上把「彼岸」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：自己主要阶段把墓地的这张卡除外，以场上1只「彼岸」怪兽为对象才能发动。那只怪兽的攻击力·守备力直到下次的对方回合结束时上升800。这个效果在这张卡送去墓地的回合不能发动。'),
(78243409, 'The Thing in the Crater', '火山口的潜伏者', '火口に潜む者', 'Effect Monster', 'Pyro', 'FIRE', 4, 1000, 1200, '当这张卡从场上被破坏送去墓地时，可以从手卡特殊召唤1只炎族怪兽上场。'),
(18180762, 'The Thing That Hides in the Mud', '泥浆潜居者', '泥に潜み棲むもの', 'Normal Monster', 'Rock', 'EARTH', 4, 1200, 1300, '脚下粘呼呼的溶化时、是这家伙出现的前兆。'),
(78697395, 'The Third Sarcophagus', '第三之棺', '第三の棺', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡只能通过「第一之棺」的效果上场。'),
(74405783, 'The Three Brave Swordsouls', '三英的相剑师', '三英の相剣師', 'Synchro Monster', 'Spellcaster', 'LIGHT', 8, 2500, 2500, '4星调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。攻击力和守备力的数值相同的1只4·8星的魔法师族怪兽从自己的卡组·墓地加入手卡。 ②：以场上1张表侧表示卡为对象才能发动。那张卡的效果无效。自己墓地有「艾克莉西娅」怪兽或「阿不思的落胤」存在的场合，可以再把作为对象的卡破坏。'),
(83404468, 'The Toil of the Normal', '一色万骨', '一色万骨', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己墓地的通常怪兽种类的以下效果各适用。 ●1种类以上：这个回合中，自己场上的通常怪兽的攻击力上升800。 ●2种类以上：场上1只效果怪兽的效果直到回合结束时无效。 ●3种类以上：这个回合中，自己场上的通常怪兽不会被效果破坏。 ●4种类以上：场上1只效果怪兽回到卡组。 ●5种类以上：从卡组把1张「一色万骨」加入手卡。'),
(46652477, 'The Transmigration Prophecy', '转生之预言', '転生の予言', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以双方墓地的卡合计2张为对象才能发动。那些卡回到持有者卡组。'),
(20036055, 'The Traveler and the Burning Abyss', '旅人的到彼岸', '旅人の到彼岸', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「旅人之到彼岸」在1回合只能发动1张。 ①：以自己墓地的这个回合被送去墓地的「彼岸」怪兽任意数量为对象才能发动。那些怪兽守备表示特殊召唤。'),
(14778250, 'The Tricky', '诡术师', 'THE トリッキー', 'Effect Monster', 'Spellcaster', 'WIND', 5, 2000, 1200, '①：这张卡可以丢弃1张手卡，从手卡特殊召唤。'),
(3912064, 'The Tripper Mercury', '轻盈水星', 'The tripping MERCURY', 'Effect Monster', 'Aqua', 'WATER', 8, 2000, 2000, '①：这张卡上级召唤成功时才能发动。场上的怪兽全部变成表侧攻击表示。 ②：这张卡也能把3只怪兽解放作召唤。 ③：只要这张卡的②的方法召唤的这张卡在怪兽区域存在，对方场上的怪兽的攻击力下降那怪兽的原本攻击力数值。 ④：这张卡在同1次的战斗阶段中可以作2次攻击。'),
(38479725, 'The Trojan Horse', '特洛伊木马', 'トロイホース', 'Effect Monster', 'Beast', 'EARTH', 4, 1600, 1200, '作为地属性怪兽祭品召唤的场合，这只怪兽1只可以作为2只份的祭品使用。'),
(39913299, 'The True Name', '真实之名', '真実の名', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：宣言1个卡名才能发动。自己卡组最上面的卡翻开，宣言的卡的场合，那张卡加入手卡。并且，可以再从卡组把1只神属性怪兽加入手卡或特殊召唤。不是的场合，翻开的卡送去墓地。'),
(11587414, 'The True Sun God', '真正的太阳神', '真なる太陽神', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，除「真正的太阳神」外的1只「太阳神之翼神龙」或者1张有那个卡名记述的卡从卡组加入手卡。 ②：「太阳神之翼神龙」以外的特殊召唤的怪兽在那个回合不能攻击。 ③：1回合1次，自己主要阶段才能发动。这张卡或者卡组1只「太阳神之翼神龙-不死鸟」送去墓地。那之后，选自己场上1只「太阳神之翼神龙」送去墓地。'),
(88071625, 'The Tyrant Neptune', '暴君海王星', 'The tyrant NEPTUNE', 'Effect Monster', 'Reptile', 'WATER', 10, NULL, NULL, '这张卡不能特殊召唤。这张卡可以把1只怪兽解放作上级召唤。这张卡的攻击力·守备力上升上级召唤时解放的怪兽的原本的攻击力·守备力各自合计数值。这张卡上级召唤成功时，选择墓地存在的1只解放的效果怪兽，当作和那只怪兽同名卡使用，得到相同效果。'),
(56920308, 'The Ultimate Creature of Destruction', '强韧！无敌！最强！', '強靭！無敵！最強！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1只「青眼」怪兽为对象才能发动。这个回合，那只表侧表示怪兽不会被战斗破坏，不受自身以外的卡的效果影响，和那只怪兽进行战斗的怪兽在伤害步骤结束时破坏。 ②：这张卡在墓地存在的状态，自己把「青眼白龙」召唤·特殊召唤的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(65475294, 'The Unfriendly Amazon', '杀戮同伴的女骑士', '味方殺しの女騎士', 'Effect Monster', 'Warrior', 'EARTH', 4, 2000, 1000, '每次自己的准备阶段，如果不用这张卡以外的1只怪兽做祭品维持，这张卡破坏。'),
(27618634, 'The Unhappy Girl', '不幸的少女', '薄幸の乙女', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 400, 300, '以表侧攻击表示存在的这张卡不会被战斗破坏。只要这张卡以表侧攻击表示存在于场上，与这张卡进行过战斗的怪兽不能再攻击及改变表示形式。（伤害计算适用）'),
(51275027, 'The Unhappy Maiden', '不幸的美少女', '薄幸の美少女', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, NULL, 100, '这张卡被战斗破坏送去墓地，当时那个回合的战斗阶段结束。'),
(83257450, 'The Unstoppable Exodia Incarnate', '幻之召唤神 艾克佐迪亚', '幻の召喚神エクゾディア', 'Fusion Monster', 'Spellcaster', 'DARK', 10, -1, NULL, '「被封印」怪兽×5 ①：场上的这张卡不会被对方的效果破坏。 ②：1回合1次，这张卡进行战斗的伤害计算时才能发动。这张卡的攻击力上升自己基本分数值。 ③：1回合1次，魔法·陷阱卡的效果发动时才能发动。那个发动无效。 ④：自己·对方的结束阶段才能发动。从卡组把1张「艾格佐德」魔法·陷阱卡在自己场上盖放。 ⑤：自己准备阶段发动。自己失去1000基本分。'),
(93788854, 'The Wandering Doomed', '彷徨的亡者', 'さまよえる亡者', 'Normal Monster', 'Zombie', 'DARK', 2, 800, 600, '因不能成佛，而只能漫无目的徘徊的怪兽。'),
(95281259, 'The Warrior Returning Alive', '战士生还', '戦士の生還', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只战士族怪兽为对象才能发动。那只战士族怪兽加入手卡。'),
(52834429, 'The Weather Auroral Canvas', '极光之天气模样', 'オーロラの天気模様', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「极光之天气模样」在自己场上只能有1张表侧表示存在。 ②：和这张卡相同纵列的自己的主要怪兽区域以及那些两邻的自己的主要怪兽区域存在的「天气」效果怪兽得到以下效果。 ●只让卡1张加入自己或者对方的手卡时，把这张卡除外才能发动。加入手卡的那张卡除外，那个玩家从卡组抽1张。'),
(53956001, 'The Weather Cloudy Canvas', '阴之天气模样', '曇りの天気模様', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「阴之天气模样」在自己场上只能有1张表侧表示存在。 ②：和这张卡相同纵列的自己的主要怪兽区域以及那些两邻的自己的主要怪兽区域存在的「天气」效果怪兽得到以下效果。 ●把这张卡除外，以场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽的攻击力变成一半，可以直接攻击。这个效果在伤害步骤不能发动，对方回合也能发动。'),
(18720257, 'The Weather Forecast', '天气预报', '天気予報', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②③的效果1回合各能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组选1张「天气」魔法·陷阱卡在自己的魔法与陷阱区域表侧表示放置。 ②：自己把「天气」连接怪兽连接召唤的场合，可以让自己的魔法与陷阱区域的表侧表示的「天气」卡作为「天气」怪兽来成为连接素材。 ③：自己主要阶段才能发动。从手卡把1只「天气」怪兽召唤。'),
(27784944, 'The Weather Painter Aurora', '极天气 川绿', '極天気ランブラ', 'Effect Monster', 'Fairy', 'DARK', 6, 2200, 2000, '①：这张卡召唤成功时才能发动。从自己的手卡·卡组·墓地选1张「天气」魔法·陷阱卡在自己的魔法与陷阱区域表侧表示放置。 ②：只要这张卡在怪兽区域存在，自己场上的「天气」魔法·陷阱卡不会成为对方的效果的对象，不会被对方的效果破坏。 ③：场上的这张卡为让「天气」卡的效果发动而被除外的场合，下个回合的准备阶段才能发动。除外的这张卡特殊召唤。'),
(28806532, 'The Weather Painter Cloud', '昙天气 糸紫', '曇天気スレット', 'Effect Monster', 'Fairy', 'WIND', 3, 1500, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在自己场上存在，这张卡以外的自己场上的表侧表示的「天气」卡被送去墓地的场合，以自己墓地最多2张「天气」魔法·陷阱卡为对象才能发动。那些卡在自己的魔法与陷阱区域表侧表示放置。 ②：场上的这张卡为让「天气」卡的效果发动而被除外的场合，下个回合的准备阶段才能发动。除外的这张卡特殊召唤。'),
(95515518, 'The Weather Painter Moonbow', '月天气 彩虹', '月天気アルシエル', 'Link Monster', 'Fairy', 'DARK', NULL, 2400, NULL, '「天气」怪兽3只 ①：这张卡连接召唤成功的场合才能发动。选除外的1只自己的「天气」怪兽特殊召唤。 ②：这张卡所连接区的「天气」效果怪兽得到以下效果。 ●自己·对方回合，把这张卡除外，以对方场上1只怪兽为对象才能发动。那只怪兽直到下个回合的准备阶段除外。 ③：连接召唤的这张卡被破坏的场合才能发动。从额外卡组把1只「虹天气 彩虹」特殊召唤。'),
(92411493, 'The Weather Painter Rain', '雨天气 湛蓝', '雨天気ラズラ', 'Effect Monster', 'Fairy', 'WATER', 3, 1200, 1400, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从手卡选1张「天气」魔法·陷阱卡在自己的魔法与陷阱区域表侧表示放置。 ②：场上的这张卡为让「天气」卡的效果发动而被除外的场合，下个回合的准备阶段才能发动。除外的这张卡特殊召唤。'),
(54178659, 'The Weather Painter Rainbow', '虹天气 彩虹', '虹天気アルシエル', 'Link Monster', 'Fairy', 'LIGHT', NULL, 2400, NULL, '「天气」怪兽3只 ①：这张卡所连接区的「天气」效果怪兽得到以下效果。 ●魔法·陷阱·怪兽的效果发动时，把这张卡除外才能发动。那个发动无效并破坏。 ②：对方把怪兽特殊召唤之际，把连接召唤的这张卡送去墓地才能发动。那次特殊召唤无效，那些怪兽破坏。 ③：场上的这张卡为让「天气」卡的效果发动而被除外的场合，下个回合的准备阶段才能发动。除外的这张卡特殊召唤。'),
(65017789, 'The Weather Painter Snow', '雪天气 天蓝', '雪天気シエル', 'Effect Monster', 'Fairy', 'EARTH', 3, NULL, 2200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从卡组选1张「天气」魔法·陷阱卡在自己的魔法与陷阱区域表侧表示放置。 ②：场上的这张卡为让「天气」卡的效果发动而被除外的场合，下个回合的准备阶段才能发动。除外的这张卡特殊召唤。'),
(54895237, 'The Weather Painter Sun', '晴天气 锈红', '晴天気ベンガーラ', 'Effect Monster', 'Fairy', 'FIRE', 3, 1600, 400, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在墓地存在的场合，把自己场上1张表侧表示的永续魔法·永续陷阱卡送去墓地才能发动。这张卡守备表示特殊召唤，从手卡选1张「天气」魔法·陷阱卡在自己的魔法与陷阱区域表侧表示放置。 ②：场上的这张卡为让「天气」卡的效果发动而被除外的场合，下个回合的准备阶段才能发动。除外的这张卡特殊召唤。'),
(91299846, 'The Weather Painter Thunder', '雷天气 姜黄', '雷天気ターメル', 'Effect Monster', 'Fairy', 'LIGHT', 3, 1700, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：把自己场上1张表侧表示的永续魔法·永续陷阱卡送去墓地才能发动。从卡组选1张「天气」魔法·陷阱卡在自己的魔法与陷阱区域表侧表示放置。 ②：场上的这张卡为让「天气」卡的效果发动而被除外的场合，下个回合的准备阶段才能发动。除外的这张卡特殊召唤。'),
(74218258, 'The Weather Rainbowed Canvas', '虹之天气模样', '虹の天気模様', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「虹之天气模样」在自己场上只能有1张表侧表示存在。 ②：和这张卡相同纵列的自己的主要怪兽区域以及那些两邻的自己的主要怪兽区域存在的「天气」效果怪兽得到以下效果。 ●对方场上有怪兽存在的场合，把这张卡除外才能发动。从卡组把和这张卡卡名不同的1只「天气」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不能从卡组把怪兽特殊召唤。这个效果在对方回合也能发动。'),
(27561302, 'The Weather Rainy Canvas', '雨之天气模样', '雨の天気模様', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「雨之天气模样」在自己场上只能有1张表侧表示存在。 ②：和这张卡相同纵列的自己的主要怪兽区域以及那些两邻的自己的主要怪兽区域存在的「天气」效果怪兽得到以下效果。 ●把这张卡除外，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡回到持有者手卡。这个效果在对方回合也能发动。'),
(80577258, 'The Weather Snowy Canvas', '雪之天气模样', '雪の天気模様', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「雪之天气模样」在自己场上只能有1张表侧表示存在。 ②：和这张卡相同纵列的自己的主要怪兽区域以及那些两邻的自己的主要怪兽区域存在的「天气」效果怪兽得到以下效果。 ●把这张卡除外才能发动。从卡组把1张「天气」卡加入手卡。这个效果的发动后，直到回合结束时自己不能用抽卡以外的方法从卡组把卡加入手卡。这个效果在对方回合也能发动。'),
(89355716, 'The Weather Sunny Canvas', '晴之天气模样', '晴れの天気模様', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「晴之天气模样」在自己场上只能有1张表侧表示存在。 ②：和这张卡相同纵列的自己的主要怪兽区域以及那些两邻的自己的主要怪兽区域存在的「天气」效果怪兽得到以下效果。 ●把这张卡除外，以自己场上1只怪兽为对象才能发动。那只自己怪兽解放，从自己的手卡·墓地选和那只怪兽卡名不同的1只「天气」怪兽特殊召唤。这个效果在对方回合也能发动。'),
(16849715, 'The Weather Thundery Canvas', '雷之天气模样', '雷の天気模様', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「雷之天气模样」在自己场上只能有1张表侧表示存在。 ②：和这张卡相同纵列的自己的主要怪兽区域以及那些两邻的自己的主要怪兽区域存在的「天气」效果怪兽得到以下效果。 ●这张卡和对方怪兽进行战斗的伤害步骤开始时，把这张卡除外才能发动。那只对方怪兽回到持有者手卡。'),
(71039903, 'The White Stone of Ancients', '太古的白石', '太古の白石', 'Tuner Monster', 'Dragon', 'LIGHT', 1, 600, 500, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡被送去墓地的回合的结束阶段才能发动。从卡组把1只「青眼」怪兽特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1只「青眼」怪兽为对象才能发动。那只怪兽加入手卡。'),
(79814787, 'The White Stone of Legend', '传说的白石', '伝説の白石', 'Tuner Monster', 'Dragon', 'LIGHT', 1, 300, 250, '①：这张卡被送去墓地的场合发动。从卡组把1只「青眼白龙」加入手卡。'),
(21208154, 'The Wicked Avatar', '邪神 神之化身', '邪神アバター', 'Effect Monster', 'Fiend', 'DARK', 10, -1, -1, '这张卡不能特殊召唤。把自己场上3只怪兽解放的场合才能通常召唤。 ①：这张卡召唤成功的场合发动。用对方回合计算的2回合内，对方不能把魔法·陷阱卡发动。 ②：这张卡的攻击力·守备力变成「邪神 神之化身」以外的场上的攻击力最高的怪兽的攻击力＋100的数值。'),
(62180201, 'The Wicked Dreadroot', '邪神 恐惧之源', '邪神ドレッド・ルート', 'Effect Monster', 'Fiend', 'DARK', 10, 4000, 4000, '这张卡不能特殊召唤。把自己场上3只怪兽解放的场合才能通常召唤。 ①：只要这张卡在怪兽区域存在，这张卡以外的场上的怪兽的攻击力·守备力变成一半。'),
(57793869, 'The Wicked Eraser', '邪神 抹灭者', '邪神イレイザー', 'Effect Monster', 'Fiend', 'DARK', 10, -1, -1, '这张卡不能特殊召唤。把自己场上3只怪兽解放的场合才能通常召唤。 ①：这张卡的攻击力·守备力变成对方场上的卡数量×1000。 ②：自己主要阶段才能发动。这张卡破坏。 ③：这张卡被破坏送去墓地的场合发动。场上的卡全部破坏。'),
(6285791, 'The Wicked Worm Beast', '邪恶蠕虫兽', '邪悪なるワーム・ビースト', 'Effect Monster', 'Beast', 'EARTH', 3, 1400, 700, '①：自己结束阶段发动。场上的表侧表示的这张卡回到持有者手卡。'),
(10000010, 'The Winged Dragon of Ra', '拉之翼神龙', 'ラーの翼神竜', 'Effect Monster', 'Divine-Beast', 'DIVINE', 10, -1, -1, '这张卡不能特殊召唤。这张卡通常召唤的场合，必须把3只解放作召唤。 ①：这张卡的召唤不会被无效化。 ②：在这张卡的召唤成功时双方不能把其他卡的效果发动。 ③：这张卡召唤时，把基本分支付到变成100基本分才能发动。这张卡的攻击力·守备力上升支付的数值。 ④：支付1000基本分，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(10000090, 'The Winged Dragon of Ra - Immortal Phoenix', '拉之翼神龙－不死鸟', 'ラーの翼神竜－不死鳥', 'Effect Monster', 'Divine-Beast', 'DIVINE', 10, 4000, 4000, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。 ①：这张卡在墓地存在的状态，「太阳神之翼神龙」从场上送去自己墓地的场合发动（不能对应这个发动把效果发动）。这张卡特殊召唤。 ②：这张卡不受其他卡的效果影响。 ③：支付1000基本分才能发动。场上1只怪兽送去墓地。 ④：结束阶段发动。这张卡送去墓地，从自己的手卡·卡组·墓地把1只「太阳神之翼神龙-球体形」无视召唤条件特殊召唤。'),
(10000080, 'The Winged Dragon of Ra - Sphere Mode', '拉之翼神龙－球体形', 'ラーの翼神竜－球体形', 'Effect Monster', 'Divine-Beast', 'DIVINE', 10, -1, -1, '这张卡不能特殊召唤。这张卡通常召唤的场合，必须把自己场上3只怪兽解放在自己场上召唤或者把对方场上3只怪兽解放在对方场上召唤，召唤的这张卡的控制权在下个回合的结束阶段回归原本持有者。 ①：这张卡不能攻击，不会成为对方的攻击·效果的对象。 ②：把这张卡解放才能发动。从手卡·卡组把1只「太阳神之翼神龙」无视召唤条件并攻击力·守备力变成4000特殊召唤。'),
(92562411, 'The World Legacy', '星遗物所引导的前路', '星遺物の導く先', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「星遗物引导的前路」在自己场上只能有1张表侧表示存在。 ②：每次场上的5星以上的表侧表示怪兽被送去墓地，每有1只给这张卡放置1个指示物（最多7个）。 ③：把有7个指示物放置的这张卡送去墓地才能发动。从额外卡组把1只电子界族连接怪兽特殊召唤。'),
(5973663, 'The World Tree', '世界树', '世界樹', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次场上的植物族怪兽被破坏，给这张卡放置1个花指示物。此外，可以把这张卡放置的花指示物任意数量取除把以下效果发动。 ●1个：选择场上1只植物族怪兽，那个攻击力·守备力直到结束阶段时上升400。 ●2个：选择场上1张卡破坏。 ●3个：选择自己墓地1只植物族怪兽特殊召唤。'),
(300102001, 'The World''s Greatest Fisherman', NULL, NULL, 'Skill Card', 'Mako', NULL, NULL, NULL, NULL, NULL),
(73082255, 'The Zombie Vampire', '真血公 不死吸血鬼', '真血公ヴァンパイア', 'XYZ Monster', 'Zombie', 'DARK', 8, 3000, 2800, '8星怪兽×2只以上 把原本持有者是对方的怪兽作为这张卡的超量召唤的素材的场合，那些等级当作8星使用。这个卡名的②的效果1回合只能使用1次。 ①：双方不能把场上的这张卡作为从墓地以外特殊召唤的怪兽的效果的对象。 ②：把这张卡1个超量素材取除才能发动。从双方卡组上面把4张卡送去墓地。这个效果让怪兽被送去墓地的场合，再让自己可以把那之内的1只在自己场上特殊召唤。'),
(51838385, 'Theban Nightmare', '底比斯的梦魇', 'ナイトメアテーベ', 'Effect Monster', 'Fiend', 'LIGHT', 4, 1500, 500, '①：自己手卡和自己的魔法与陷阱区域没有卡存在的场合，这张卡的攻击力上升1500。'),
(85687952, 'Theia, the Primal Being', '原始生命态 忒伊亚', '原始生命態ティア', 'Effect Monster', 'Rock', 'DARK', 11, 3000, 600, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，把等级合计直到11以上的自己场上的怪兽解放才能发动。这张卡从手卡特殊召唤。那之后，自己场上没有其他怪兽存在的场合，可以把场上1只攻击力最高的怪兽破坏。 ②：只要这张卡在怪兽区域存在，那个期间双方1回合只能有最多4次把怪兽召唤·特殊召唤。'),
(87997872, 'Theinen the Great Sphinx', '斯芬克斯·安德鲁吉尼斯', 'スフィンクス・アンドロジュネス', 'Effect Monster', 'Beast', 'LIGHT', 10, 3500, 3000, '这张卡不能通常召唤。自己场上的「斯芬克斯·安德鲁」和「斯芬克斯·迪蕾雅」同时被破坏时，支付500基本分才能从手卡或者卡组特殊召唤。这张卡特殊召唤成功时，可以支付500基本分，直到结束阶段结束时这张卡的攻击力上升3000。'),
(98986900, 'Thelematech Clatis', '泰勒玛科技・克拉特斯', 'セレマテック・クラティス', 'XYZ Monster', 'Spellcaster', 'DARK', 8, 3000, 900, '8星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：每次对方把魔法卡以外的卡的效果发动，给这张卡放置1个魔力指示物（最多9个）。 ②：把这张卡3个魔力指示物取除才能发动。从以下效果让1个适用。 ●从卡组把1张魔法卡或1只魔法师族效果怪兽加入手卡。 ●从手卡·卡组把1只魔法师族怪兽特殊召唤。 ③：这张卡被破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(48739627, 'Theorealize', '无垢预幻视', '無垢なる予幻視', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「无垢者 米底乌斯」送去墓地才能发动。把对方卡组最上面的卡确认，回到卡组最上面或最下面。 ②：把墓地的这张卡除外，以自己场上1只表侧表示怪兽为对象，宣言种族和属性各1个才能发动。那只怪兽直到对方回合结束时变成宣言的种族·属性。'),
(27285068, 'Theorealize Liberation', '开辟预幻视', '開闢なる予幻視', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「无垢者 米底乌斯」存在的场合才能发动。从卡组选1只攻击力300/守备力200的怪兽加入手卡或特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽当作调整使用。'),
(94326720, 'Theorealize Overdrive', '破灭预幻视', '破滅なる予幻視', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己的墓地·除外状态的1只「无垢者 米底乌斯」为对象才能发动。那只怪兽特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己场上1只表侧表示怪兽为对象，宣言1～10的任意等级才能发动。那只怪兽的等级直到回合结束时变成宣言的等级。'),
(24207889, 'There Can Be Only One', '千察万别', 'センサー万別', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，相同种族的怪兽在双方场上各自只能有1只表侧表示存在。双方玩家在自身场上有相同种族的怪兽2只以上存在的场合，直到相同种族的怪兽变成1只为止必须送去墓地。'),
(84332527, 'Therion "Bull" Ain', '兽带斗士“猛牛”艾英', 'セリオンズ“ブルズ”アイン', 'Effect Monster', 'Warrior', 'FIRE', 7, 2100, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「兽带斗神」怪兽或者战士族怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽当作装备卡使用给这张卡装备。 ②：以自己场上1张「兽带斗神」卡和对方场上1张卡为对象才能发动。那些卡破坏。 ③：有这张卡装备的「兽带斗神」怪兽攻击力上升700，得到这个卡名的②的效果。'),
(57111330, 'Therion "Duke" Yul', '兽带斗士“公爵”猷尔', 'セリオンズ“デューク”ユール', 'Effect Monster', 'Psychic', 'LIGHT', 8, 2100, 2800, '这个卡名的①的效果1回合只能使用1次。 ①：以自己墓地1只「兽带斗神」怪兽或者念动力族怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽当作装备卡使用给这张卡装备。 ②：只要自己场上有装备卡存在，自己场上的「兽带斗神」怪兽不会被对方的效果破坏。 ③：有这张卡装备的「兽带斗神」怪兽攻击力上升700，得到这个卡名的②的效果。'),
(48806195, 'Therion "Empress" Alasia', '兽带斗士“女帝”阿拉西娅', 'セリオンズ“エンプレス”アラシア', 'Effect Monster', 'Reptile', 'EARTH', 8, 2100, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「兽带斗神」怪兽或者爬虫类族怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽当作装备卡使用给这张卡装备。 ②：丢弃1张手卡，以自己的魔法与陷阱区域1张「兽带斗神」怪兽卡为对象才能发动。那张卡特殊召唤。 ③：有这张卡装备的「兽带斗神」怪兽攻击力上升700，得到这个卡名的②的效果。'),
(10604644, 'Therion "King" Regulus', '兽带斗士“王者”雷古拉斯', 'セリオンズ“キング”レギュラス', 'Effect Monster', 'Machine', 'EARTH', 8, 2800, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「兽带斗神」怪兽或机械族怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽当作装备魔法卡使用给这张卡装备。 ②：对方把效果发动时，从自己的手卡·场上（表侧表示）把1张「兽带斗神」怪兽卡送去墓地才能发动。那个效果无效。 ③：有这张卡装备的「兽带斗神」怪兽攻击力上升700，得到这个卡名的②的效果。'),
(83610035, 'Therion "Lily" Borea', '兽带斗士“百合”玻莱雅', 'セリオンズ“リリー”ボレア', 'Effect Monster', 'Plant', 'WIND', 8, 2400, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「兽带斗神」怪兽或者植物族怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽当作装备卡使用给这张卡装备。 ②：从自己的手卡·场上把1张卡送去墓地才能发动。从卡组把1张「兽带斗神」魔法·陷阱卡加入手卡。 ③：有这张卡装备的「兽带斗神」怪兽攻击力上升700，得到这个卡名的②的效果。'),
(21727231, 'Therion "Reaper" Fum', '兽带斗士“收割者”伐姆', 'セリオンズ“リーパー”ファム', 'Effect Monster', 'Aqua', 'WATER', 7, 1400, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「兽带斗神」怪兽或者水族怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽当作装备卡使用给这张卡装备。 ②：对方回合，以自己的魔法与陷阱区域1张「兽带斗神」卡和对方场上1张卡为对象才能发动。那些卡回到持有者手卡。 ③：有这张卡装备的「兽带斗神」怪兽攻击力上升700，得到这个卡名的②的效果。'),
(57285770, 'Therion Charge', '兽带斗士・充能', 'セリオンズ・チャージ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·魔法与陷阱区域（表侧表示）把1张「兽带斗神突击」以外的「兽带斗神」卡或者「无尽机关 银星系统」送去墓地才能发动。自己抽2张。'),
(43270827, 'Therion Cross', '兽带斗士・交叉击', 'セリオンズ・クロス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「兽带斗神」怪兽存在，对方把怪兽的效果发动时，可以从以下效果选择1个发动（自己墓地有「无尽机关 银星系统」存在的场合，可以选择两方）。 ●那个发动的效果无效。 ●那只怪兽除外。'),
(84792926, 'Therion Discolosseum', '圆盘斗技场 兽带斗士擂台', '円盤闘技場セリオンズ・リング', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「兽带斗神」怪兽加入手卡。 ②：1回合1次，自己怪兽被战斗破坏的场合，可以作为代替从卡组把1张「兽带斗神」卡或者「无尽机关 银星系统」送去墓地。 ③：1回合1次，自己或者对方的怪兽被战斗破坏送去墓地时，以自己墓地1只「兽带斗神」怪兽为对象才能发动。那只怪兽加入手卡。'),
(75290703, 'Therion Irregular', '兽带斗士・异雷古拉', 'セリオンズ・イレギュラー', 'Effect Monster', 'Machine', 'DARK', 10, 1600, 2800, '这个卡名的①②③的效果1回合各能使用1次。 ①：以自己墓地最多3只「兽带斗神」怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽当作装备卡使用给这张卡装备。 ②：从手卡丢弃1张「无尽机关 银星系统」才能发动。对方场上的卡全部破坏。 ③：这张卡装备中的场合才能发动。这张卡特殊召唤。那之后，这张卡装备过的怪兽当作装备卡使用给这张卡装备。'),
(79775821, 'Therion Stand Up!', '兽带斗士・站起来啊', 'セリオンズ・スタンダップ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己墓地1只「兽带斗神」怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以从自己的手卡·墓地把1只「兽带斗神」怪兽当作装备卡使用给那只怪兽装备。 ②：自己·对方的主要阶段，把墓地的这张卡除外，从自己的场上·墓地各以1只「兽带斗神」怪兽为对象才能发动。那只墓地的怪兽当作装备卡使用给那只自己场上的怪兽装备。'),
(6588580, 'Thermal Genex', '热力次代机', 'サーマル・ジェネクス', 'Synchro Monster', 'Machine', 'FIRE', 8, 2400, 1200, '「次世代控制员」＋调整以外的炎属性怪兽1只以上 ①：这张卡的攻击力上升自己墓地的炎属性怪兽数量×200。 ②：这张卡战斗破坏对方怪兽的场合发动。给与对方为自己墓地的「次世代」怪兽数量×200伤害。'),
(26205777, 'Thestalos the Firestorm Monarch', '炎帝泰斯塔罗斯', '炎帝テスタロス', 'Effect Monster', 'Pyro', 'FIRE', 6, 2400, 1000, '①：这张卡上级召唤成功的场合发动。对方手卡随机选1张丢弃。丢弃的卡是怪兽卡的场合，给与对方那只怪兽的等级×100伤害。'),
(69230391, 'Thestalos the Mega Monarch', '爆炎帝泰斯塔罗斯', '爆炎帝テスタロス', 'Effect Monster', 'Pyro', 'FIRE', 8, 2800, 1000, '这张卡可以把1只上级召唤的怪兽解放作上级召唤。 ①：这张卡上级召唤的场合发动。把对方手卡确认，选那之内的1张丢弃。丢弃的卡是怪兽的场合，给与对方那只怪兽的等级×200伤害。这张卡把炎属性怪兽解放作上级召唤的场合，那个时候的效果加上以下效果。 ●给与对方1000伤害。'),
(77832858, 'Thestalos the Shadowfire Monarch', '邪炎帝王泰斯塔罗斯', '邪炎帝王テスタロス', 'Effect Monster', 'Pyro', 'FIRE', 10, 3000, 1000, '这张卡可以把对方场上1只怪兽和上级召唤的1只自己怪兽解放作上级召唤。 ①：这张卡上级召唤的场合才能发动。对方手卡随机1张除外，给与对方1000伤害。把上级召唤的8星以上的怪兽解放让这张卡上级召唤的场合，可以再让以下效果适用。 ●场上1张卡除外，那张卡是炎·暗属性怪兽卡的场合，给与对方那个原本等级×200伤害。'),
(4599182, 'This Creepy Little Punk', '归来的死神', '舞い戻った死神', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「永火」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地的怪兽以及除外的自己怪兽之中选1只「永火」怪兽特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的「永火」怪兽因对方的效果从场上离开的场合或者被战斗破坏的场合才能发动。这张卡在自己场上盖放。'),
(30604579, 'Thor, Lord of the Aesir', '极神皇 托尔', '極神皇トール', 'Synchro Monster', 'Beast-Warrior', 'EARTH', 10, 3500, 2800, '「极星兽」调整＋调整以外的怪兽2只以上 ①：1回合1次，自己主要阶段才能发动。对方场上的全部表侧表示怪兽的效果直到回合结束时无效化。 ②：场上的表侧表示的这张卡被对方破坏送去墓地的回合的结束阶段，从自己墓地把1只「极星兽」调整除外才能发动。这张卡从墓地特殊召唤。 ③：这张卡的②的效果特殊召唤成功时才能发动。给与对方800伤害。'),
(72374522, 'Thorn Fangs of Violet Poison', '紫毒之茨牙', '紫毒の茨牙', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「捕食」卡使用。 ①：以自己场上1只「凶饿毒融合龙」为对象才能发动。持有比那只怪兽低的攻击力的对方场上的怪兽全部破坏。那之后，以下效果可以适用。这个回合，作为对象的怪兽不能攻击。 ●自己手卡全部丢弃，给与对方这个效果破坏的怪兽的原本攻击力合计数值的伤害。'),
(65079854, 'Thorn of Malice', '憎恶之棘', '憎悪の棘', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「黑蔷薇龙」或者植物族怪兽才能装备。装备怪兽的攻击力上升600。装备怪兽攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。装备怪兽向怪兽攻击的场合，伤害计算后攻击对象怪兽的攻击力·守备力下降600。和装备怪兽进行战斗的对方怪兽不会被那次战斗破坏。'),
(70780151, 'Thought Ruler Archfiend', '心灵领域恶魔', 'メンタルスフィア・デーモン', 'Synchro Monster', 'Psychic', 'DARK', 8, 2700, 2300, '调整＋调整以外的怪兽1只以上 ①：这张卡战斗破坏怪兽送去墓地的场合发动。自己基本分回复那只怪兽的原本攻击力的数值。 ②：只以念动力族怪兽1只为对象的魔法·陷阱卡发动时，支付1000基本分才能发动。那个发动无效并破坏。'),
(41462083, 'Thousand Dragon', '千年龙', '千年竜', 'Fusion Monster', 'Dragon', 'WIND', 7, 2400, 2000, '「时间魔术师」＋「宝贝龙」'),
(5703682, 'Thousand Energy', '千之能量', 'サウザンドエナジー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上所有以表侧表示存在的2星通常怪兽（衍生物除外）的原本的攻击力·守备力上升1000点。结束阶段时，自己场上存在的2星通常怪兽全部破坏。'),
(63391643, 'Thousand Knives', '千把刀', '千本ナイフ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「黑魔术师」存在的场合，以对方场上1只怪兽为对象才能发动。那只对方怪兽破坏。'),
(33977496, 'Thousand Needles', '千根针', '針千本', 'Effect Monster', 'Beast', 'EARTH', 4, 1000, 1800, '守备表示的这张卡受到攻击时，若这张卡的守备力超过对方攻击怪兽的攻击力，伤害步骤结束时那只攻击怪兽破坏。'),
(27125110, 'Thousand-Eyes Idol', '千眼邪教神', '千眼の邪教神', 'Normal Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '操纵人心的邪神。千只邪眼会看透人的负面之心并使其增大。'),
(81434470, 'Thousand-Eyes Jellyfish', '千眼卵鱼', 'サウザンド・アイズ・フィッシュ', 'Effect Monster', 'Fish', 'WATER', 5, 300, 2100, '这张卡不能通常召唤，把自己场上存在的1只「海洋怪鱼卫士」解放的场合才能特殊召唤。只要这张卡在自己场上表侧表示存在，对方必须把手卡持续公开。'),
(63519819, 'Thousand-Eyes Restrict', '千眼纳祭魔', 'サウザンド・アイズ・サクリファイス', 'Fusion Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '「纳祭之魔」＋「千眼邪教神」 ①：只要这张卡在怪兽区域存在，这张卡以外的场上的怪兽不能攻击，也不能作表示形式的变更。 ②：1回合1次，以对方场上1只怪兽为对象才能发动。那只对方怪兽当作装备卡使用给这张卡装备（只有1只可以装备）。 ③：这张卡的攻击力·守备力变成这张卡的效果装备的怪兽的各自数值，这张卡被战斗破坏的场合，作为代替把装备的那只怪兽破坏。'),
(300204003, 'Thousand-Eyes Spell', NULL, NULL, 'Skill Card', 'Pegasus', NULL, NULL, NULL, NULL, NULL),
(36361633, 'Threatening Roar', '威吓之咆哮', '威嚇する咆哮', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合对方不能攻击宣言。'),
(50838440, 'Three in One', '三位一体', '三位一体', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方结束阶段，对方的手卡·场上的卡数量比自己的手卡·场上的卡数量多的场合才能发动。从自己墓地把3只通常怪兽特殊召唤。 ②：把墓地的这张卡除外，以原本卡名不同的自己场上3张怪兽卡为对象才能发动。把有那3张卡的原本卡名全部记述的1张魔法·陷阱卡从手卡·卡组到自己场上盖放。'),
(47594192, 'Three of a Kind', '三条', 'スリーカード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有衍生物以外的同名怪兽3只以上存在的场合才能发动。选择对方场上3张卡破坏。'),
(95081386, 'Three Strikes Barrier', '三振障壁', 'スリーストライク・バリア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上的卡只有3张的场合，可以从以下效果选择1个发动。 ●这个回合，自己怪兽不会被战斗破坏。 ●这个回合，自己受到的战斗伤害变成0。 ●这个回合，每次自己怪兽给与对方战斗伤害，自己基本分回复那个数值。'),
(7852878, 'Three Thousand Needles', '三千根针', '針三千本', 'Effect Monster', 'Beast', 'EARTH', 8, 3000, 1800, '守备表示的这张卡受到攻击的场合，若这张卡的守备力超过对方攻击怪兽的攻击力，伤害步骤结束时那只攻击怪兽破坏。'),
(43464884, 'Three Trolling Trolls', '妖海的巨魔歹徒', '妖海のアウトロール', 'Tuner Monster', 'Beast-Warrior', 'WATER', 3, 1000, 1300, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是兽战士族怪兽不能特殊召唤。 ①：这张卡召唤·特殊召唤成功的场合，以自己墓地1只兽战士族怪兽为对象才能发动。这张卡的属性·等级直到回合结束时变成和那只怪兽相同。 ②：自己主要阶段才能发动。把持有和这张卡相同属性·等级的1只兽战士族怪兽从手卡特殊召唤。'),
(31464658, 'Three-Eyed Ghost', '三眼死灵', '三眼の死霊', 'Effect Monster', 'Fiend', 'DARK', 3, 900, 800, '这个卡名的效果1回合只能使用1次。 ①：把场上的这张卡送去墓地才能发动。从卡组把1只暗属性·10星怪兽加入手卡。'),
(78423643, 'Three-Headed Geedo', '三头基多', '三ツ首のギドー', 'Normal Monster', 'Fiend', 'DARK', 4, 1200, 1400, '有三个头的怪兽，性格非常凶暴。'),
(33734439, 'Three-Legged Zombies', '二人三脚丧尸', '２人３脚ゾンビ', 'Normal Monster', 'Zombie', 'DARK', 3, 1100, 800, '瘦子和胖子，友好的骸骨二人组，走起路来很艰难。'),
(31944175, 'Threshold Borg', '阈电压电子人', 'スレッショルド・ボーグ', 'Effect Monster', 'Cyberse', 'EARTH', 7, 2400, 2000, '①：自己场上没有怪兽存在的场合，这张卡可以把手卡1只电子界族怪兽丢弃，从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，对方场上的怪兽的攻击力下降500。'),
(12332865, 'Thron the Disciplined Angel', '圣座天嗣 坐天使', '聖座天嗣ストン', 'Effect Monster', 'Fairy', 'EARTH', 4, 1500, 600, '这个卡名的效果1回合只能使用1次。 ①：原本的种族·属性是天使族·地属性的怪兽从自己的手卡·场上送去墓地的场合才能发动。这张卡从手卡特殊召唤。'),
(63679166, 'Throne of the Archfiends', '恶魔王座', 'スローン・オブ・デーモンズ', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，把自己的手卡·额外卡组（表侧）·墓地·除外状态的1只「恶魔」仪式怪兽仪式召唤。 ②：自己·对方的准备阶段，自己的额外卡组有表侧的「死亡皇帝恶魔」存在的场合才能发动。墓地·除外状态的这张卡加入手卡。'),
(76075810, 'Throwstone Unit', '投石部队', '投石部隊', 'Effect Monster', 'Warrior', 'EARTH', 4, 900, 2000, '自己的场上的1只战士族怪兽做祭品。持有这张卡的攻击力以下的守备力的表侧表示的1只怪兽破坏。'),
(84813516, 'Thunder Ball', '铁球魔神 戈逻工', '鉄球魔神ゴロゴーン', 'Effect Monster', 'Fiend', 'DARK', 3, 450, 400, '这个卡名的①②③的效果1回合各能使用1次。 ①：怪兽进行战斗的伤害步骤结束时才能发动。这张卡从手卡特殊召唤。 ②：从手卡以及自己场上盖放的卡之中把1张陷阱卡送去墓地才能发动。和这张卡相同纵列的其他怪兽全部破坏。 ③：怪兽区域的这张卡被战斗·效果破坏送去墓地的场合，以自己墓地1张卡为对象才能发动。掷1次骰子。6出现的场合，作为对象的卡加入手卡。'),
(69196160, 'Thunder Crash', '雷轰', 'サンダー・クラッシュ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '破坏自己场上存在的所有怪兽。对对方造成被破坏的怪兽数量×300点的伤害。'),
(27623932, 'Thunder Discharge', '雷霆喷射', 'サンダー・ディスチャージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「勇者衍生物」存在的场合，以把有「勇者衍生物」的衍生物名记述的装备卡装备的自己场上1只怪兽为对象才能发动。持有那只怪兽的攻击力以下的攻击力的对方场上的怪兽全部破坏。那之后，可以从自己的手卡·墓地选有「勇者衍生物」的衍生物名记述的1张装备魔法卡给自己场上1只可以装备的怪兽装备。'),
(31786629, 'Thunder Dragon', '雷龙', 'サンダー・ドラゴン', 'Effect Monster', 'Thunder', 'LIGHT', 5, 1600, 1500, '①：把这张卡从手卡丢弃才能发动。从卡组把最多2只「雷龙」加入手卡。'),
(15291624, 'Thunder Dragon Colossus', '超雷龙', '超雷龍－サンダー・ドラゴン', 'Fusion Monster', 'Thunder', 'DARK', 8, 2600, 2400, '「雷龙」＋雷族怪兽 这张卡用融合召唤以及以下方法才能特殊召唤。 ●雷族怪兽的效果在手卡发动的回合，把融合怪兽以外的自己场上1只雷族效果怪兽解放的场合可以从额外卡组特殊召唤。 ①：只要这张卡在怪兽区域存在，对方不能用抽卡以外的方法从卡组把卡加入手卡。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替把自己墓地1只雷族怪兽除外。'),
(18444733, 'Thunder Dragon Discharge', '雷龙放电', '雷龍放電', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己的雷族怪兽的效果的发动不会被无效化。 ②：1回合1次，自己场上有「雷龙」怪兽召唤·特殊召唤的场合，以场上1张魔法·陷阱卡为对象才能发动。从卡组把1只雷族怪兽除外，作为对象的卡破坏。'),
(95238394, 'Thunder Dragon Fusion', '雷龙结合', '雷龍融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的场上·墓地·除外状态的怪兽作为融合素材回到卡组，把1只雷族融合怪兽融合召唤。 ②：把这个回合没有送去墓地的这张卡从墓地除外才能发动。从卡组把1只雷族怪兽加入手卡。'),
(12081875, 'Thunder Dragon Thunderstormech', '轰机雷龙', '轟雷機龍－サンダー・ドラゴン', 'Link Monster', 'Thunder', 'LIGHT', NULL, 2800, NULL, '雷族怪兽2只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡是已连接召唤的场合，从自己墓地的怪兽以及除外的自己怪兽之中以1只「雷龙」怪兽为对象才能发动。那只怪兽记述的把自身从手卡丢弃发动的效果适用。那之后，那只怪兽回到卡组最上面或者最下面。 ②：自己场上的雷族怪兽被战斗·效果破坏的场合，可以作为代替把自己墓地3张卡除外。'),
(41685633, 'Thunder Dragon Titan', '神雷龙', '雷神龍－サンダー・ドラゴン', 'Fusion Monster', 'Thunder', 'LIGHT', 10, 3200, 3200, '「雷龙」怪兽×3 这张卡用融合召唤以及以下方法才能特殊召唤。 ●把手卡1只雷族怪兽和「雷神龙-雷龙」以外的自己场上1只雷族融合怪兽除外的场合可以从额外卡组特殊召唤。 ①：雷族怪兽的效果在手卡发动时才能发动（伤害步骤也能发动）。场上1张卡破坏。 ②：场上的这张卡被效果破坏的场合，可以作为代替把自己墓地2张卡除外。'),
(56713174, 'Thunder Dragondark', '暗雷龙', '雷電龍－サンダー・ドラゴン', 'Effect Monster', 'Thunder', 'DARK', 5, 1600, 1500, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己·对方回合，把这张卡从手卡丢弃才能发动。从卡组把1只「雷电龙-雷龙」加入手卡。 ②：这张卡被除外的场合或者从场上送去墓地的场合才能发动。从卡组把「雷电龙-雷龙」以外的1张「雷龙」卡加入手卡。'),
(55591586, 'Thunder Dragonduo', '劫雷龙', '雷劫龍－サンダー・ドラゴン', 'Effect Monster', 'Thunder', 'DARK', 8, 2800, NULL, '这张卡不能通常召唤。从自己墓地把光属性和暗属性的怪兽各1只除外的场合可以特殊召唤。 ①：1回合1次，怪兽的效果在手卡发动的场合发动。这张卡的攻击力直到回合结束时上升300。 ②：这张卡战斗破坏对方怪兽时，从自己墓地把1张卡除外才能发动。从卡组把1只雷族怪兽加入手卡。 ③：对方结束阶段，以除外的1张自己的卡为对象才能发动。那张卡回到卡组最上面或者最下面。'),
(83107873, 'Thunder Dragonhawk', '鸟雷龙', '雷鳥龍－サンダー・ドラゴン', 'Effect Monster', 'Thunder', 'LIGHT', 6, 1800, 2200, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把这张卡从手卡丢弃才能发动。「雷鸟龙-雷龙」以外的自己的墓地·除外状态的1只「雷龙」怪兽特殊召唤。 ②：这张卡被除外的场合或者从场上送去墓地的场合才能发动。自己手卡任意数量回到卡组。那之后，自己抽出回到卡组的数量。'),
(5206415, 'Thunder Dragonlord', '天震雷龙', '天雷震龍－サンダー・ドラゴン', 'Effect Monster', 'Thunder', 'LIGHT', 9, 3000, 2000, '这张卡不能通常召唤。雷族怪兽的效果在手卡发动的回合，从手卡以及自己场上的表侧表示怪兽之中把1只8星以下的雷族怪兽除外的场合可以特殊召唤。 ①：对方回合1次，从自己墓地把包含雷族怪兽的2张卡除外，以自己场上1只雷族怪兽为对象才能发动。这个回合，那只怪兽不会成为对方的效果的对象。 ②：自己结束阶段才能发动。从卡组把1张「雷龙」卡送去墓地。'),
(20318029, 'Thunder Dragonmatrix', '源雷龙', '雷源龍－サンダー・ドラゴン', 'Effect Monster', 'Thunder', 'LIGHT', 1, NULL, 2000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己·对方回合，把这张卡从手卡丢弃，以自己场上1只雷族怪兽为对象才能发动。那只怪兽的攻击力上升500。 ②：这张卡被除外的场合或者从场上送去墓地的场合才能发动。从卡组把1只「雷源龙-雷龙」加入手卡。'),
(29596581, 'Thunder Dragonroar', '兽雷龙', '雷獣龍－サンダー・ドラゴン', 'Effect Monster', 'Thunder', 'DARK', 6, 2400, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把这张卡从手卡丢弃才能发动。「雷兽龙-雷龙」以外的自己的墓地·除外状态的1张「雷龙」卡加入手卡。 ②：这张卡被除外的场合或者从场上送去墓地的场合才能发动。从卡组把1只「雷龙」怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到手卡。'),
(82045034, 'Thunder Dragons'' Hundred Thunders', '百雷之雷龙', '百雷のサンダー・ドラゴン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只雷族怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以把那些同名怪兽从自己墓地尽可能特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。只要这个效果特殊召唤的怪兽在怪兽区域存在，自己不是雷族怪兽不能特殊召唤。'),
(698785, 'Thunder End Dragon', '雷霆终结龙', 'サンダーエンド・ドラゴン', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 3000, 2000, '8星通常怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。这张卡以外的场上存在的怪兽全部破坏。'),
(16223761, 'Thunder Hand', '雷霆手', 'サンダー・ハンド', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1600, 1600, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，原本攻击力或者原本守备力是1600的自己场上的表侧表示怪兽被战斗或者对方的效果破坏送去墓地的场合才能发动。这张卡特殊召唤，选对方场上1张卡破坏。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(15510988, 'Thunder Kid', '雷电小子', 'サンダー・キッズ', 'Normal Monster', 'Thunder', 'WIND', 2, 700, 600, '在它的体内平时储蓄着雷电。因此当它哭泣时非常危险。'),
(71564252, 'Thunder King Rai-Oh', '雷王', 'ライオウ', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1900, 800, '只要这张卡在自己场上表侧表示存在，双方不能用抽卡以外的方法从卡组把卡加入手卡。此外，可以把自己场上表侧表示存在的这张卡送去墓地，让1只对方怪兽的特殊召唤无效并破坏。'),
(48770333, 'Thunder King, the Lightningstrike Kaiju', '雷击坏兽 雷霆之王', '雷撃壊獣サンダー・ザ・キング', 'Effect Monster', 'Thunder', 'LIGHT', 9, 3300, 2100, '①：这张卡可以把对方场上1只怪兽解放，从手卡往对方场上攻击表示特殊召唤。 ②：对方场上有「坏兽」怪兽存在的场合，这张卡可以从手卡攻击表示特殊召唤。 ③：「坏兽」怪兽在自己场上只能有1只表侧表示存在。 ④：1回合1次，把自己·对方场上3个坏兽指示物取除才能发动。这个回合，对方不能把魔法·陷阱·怪兽的效果发动，这张卡在同1次的战斗阶段中最多3次可以向怪兽攻击。'),
(70797118, 'Thunder Nyan Nyan', '雷电娘娘', '雷電娘々', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1900, 800, '自己场上存在光属性以外的表侧表示怪兽的场合，表侧表示的这张卡破坏。'),
(91781589, 'Thunder of Ruler', '霸者的独揽', '覇者の一括', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '在对方的准备阶段发动。对方本回合不能进行战斗阶段。'),
(14089429, 'Thunder Option Token', '蓝色雷电T45', 'ブルーサンダーT４５', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(48049769, 'Thunder Sea Horse', '雷电海马', 'サンダー・シーホース', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1600, 1200, '「雷海马」的效果1回合只能使用1次，这个效果发动的回合，自己不能把怪兽特殊召唤。 ①：把这张卡从手卡丢弃才能发动。从卡组把2只攻击力1600以下的雷族·光属性·4星的同名怪兽加入手卡。'),
(20264508, 'Thunder Short', '漏雷', 'サンダー・ショート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上存在的怪兽每有1只，给与对方基本分400分伤害。'),
(77506119, 'Thunder Unicorn', '雷电独角兽', 'サンダー・ユニコーン', 'Synchro Monster', 'Beast', 'LIGHT', 5, 2200, 1800, '兽族调整＋调整以外的怪兽1只以上 1回合1次，自己的主要阶段时选择对方场上表侧表示存在的1只怪兽才能发动。选择的怪兽的攻击力直到结束阶段时下降自己场上存在的怪兽数量×500的数值。这个效果发动的回合，这张卡以外的怪兽不能攻击。'),
(66722103, 'Thunderclap Monk', '封狼雷坊', '封狼雷坊', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1900, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把怪兽的效果发动时，把特殊召唤的这张卡解放才能发动。那个发动无效并破坏。 ②：这张卡从场上送去墓地的场合才能发动。从手卡把1只雷族怪兽守备表示特殊召唤。'),
(13683298, 'Thunderclap Skywolf', '大狼雷鸣', '大狼雷鳴', 'Effect Monster', 'Thunder', 'LIGHT', 7, 2500, 2000, '这张卡的效果发动的回合，自己不能进行战斗阶段。 ①：这张卡从墓地的特殊召唤成功的场合才能发动。对方场上的表侧表示怪兽全部破坏。'),
(42469671, 'Thunderforce Attack', '超电导波雷击炮', '超電導波サンダーフォース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡的发动和效果不会被无效化。 ①：自己场上有原本卡名是「奥西里斯之天空龙」的怪兽存在的场合才能发动。对方场上的表侧表示怪兽全部破坏。这张卡在自己主要阶段发动的场合，可以再让以下效果适用。 ●自己从卡组抽出这个效果破坏送去对方墓地的怪兽的数量。这个回合，自己只能用1只怪兽攻击。'),
(55557574, 'Thunderspeed Summon', '神速召唤', '神速召喚', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段以及战斗阶段才能发动。把1只10星怪兽召唤。自己场上有「王后骑士」「卫兵骑士」「国王骑士」全部存在的场合，可以作为代替让以下效果适用。 ●从卡组把1只暗属性以外的攻击力?的10星怪兽加入手卡。那之后，可以把1只10星怪兽召唤。'),
(26400609, 'Tidal, Dragon Ruler of Waterfalls', '瀑征龙－狂潮', '瀑征竜－タイダル', 'Effect Monster', 'Dragon', 'WATER', 7, 2600, 2000, '这个卡名的①～④的效果1回合只能有1次使用其中任意1个。 ①：从手卡把这张卡和1只水属性怪兽丢弃去墓地才能发动。从卡组把1只怪兽送去墓地。 ②：把2只龙族或水属性的怪兽从自己的手卡·墓地除外才能发动。这张卡从手卡·墓地特殊召唤。 ③：这张卡特殊召唤的场合，对方结束阶段发动。这张卡回到手卡。 ④：这张卡被除外的场合才能发动。从卡组把1只龙族·水属性怪兽加入手卡。'),
(91588074, 'Tierra, Source of Destruction', '创星神 提耶拉', '創星神 tierra', 'Effect Monster', 'Fiend', 'LIGHT', 11, 3400, 3600, '这张卡不能通常召唤。让这张卡以外的自己的手卡·场上的卡10种类回到持有者的卡组·额外卡组的场合才能特殊召唤。 ①：这张卡的特殊召唤不会被无效化。 ②：这张卡特殊召唤成功的场合发动。这张卡以外的双方的手卡·场上·墓地的卡以及额外卡组的表侧表示的灵摆怪兽全部回到持有者卡组。不能对应这个效果的发动让魔法·陷阱·怪兽的效果发动。'),
(40450317, 'Ties of the Brethren', '同胞羁绊', '同胞の絆', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能进行战斗阶段。 ①：支付2000基本分，以自己场上1只4星以下的怪兽为对象才能发动。和那只怪兽是卡名不同并是种族·属性·等级相同的2只怪兽从卡组特殊召唤（同名卡最多1张）。这张卡的发动后，直到回合结束时自己不能把怪兽特殊召唤。'),
(32270212, 'Ties That Bind', '伙伴羁绊', '仲間の絆', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有着「光之黄金柜」以及有那个卡名记述的怪兽存在的场合才能发动。把有「光之黄金柜」的卡名记述的最多2只4星以下的怪兽从手卡·卡组特殊召唤（同名卡最多1张）。这张卡的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。'),
(49791927, 'Tiger Axe', '老虎斧战士', 'タイガー・アックス', 'Normal Monster', 'Beast-Warrior', 'EARTH', 4, 1300, 1100, '手持斧子的兽战士。敏捷动作下所发的攻击很强。'),
(10097168, 'Tiger Dragon', '虎龙', 'タイガードラゴン', 'Effect Monster', 'Dragon', 'EARTH', 6, 2400, 1800, '把龙族怪兽解放对这张卡的上级召唤成功时，可以把对方的魔法与陷阱卡区域盖放的最多2张卡破坏。'),
(3129635, 'Tiki Curse', '诅咒之像', 'カース・オブ・スタチュー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后变成怪兽卡（岩石族·暗·4星·攻1800/守1000）在自己的怪兽卡区域特殊召唤。这张卡在场上当作怪兽使用而存在，这张卡以外的当作怪兽使用的陷阱卡和对方怪兽进行战斗的场合，那只对方怪兽在伤害计算后破坏。这张卡也当作陷阱卡使用。'),
(14554127, 'Tiki Peace', '和平雕像', 'ピース・オブ・スタチュー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成持有以下效果的效果怪兽（岩石族·地·4星·攻/守1800）在怪兽区域特殊召唤（也当作陷阱卡使用）。 ●自己·对方回合，支付800基本分才能发动（这个卡名的这个效果1回合只能使用1次）。「和平之像」以外的自己的墓地·除外状态的1张永续陷阱卡作为卡名当作「和平之像」使用的通常怪兽（岩石族·地·4星·攻/守1000）特殊召唤（不当作陷阱卡使用）。'),
(49514333, 'Tiki Soul', '灵魂之像', 'ソウル・オブ・スタチュー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后变成怪兽卡（岩石族·光·4星·攻1000/守1800）在自己的怪兽卡区域特殊召唤。只要这张卡在场上当作怪兽使用而存在，这张卡以外的当作怪兽使用的陷阱卡被对方破坏送去自己墓地的场合，可以不送去墓地在魔法与陷阱卡区域盖放。这张卡也当作陷阱卡使用。'),
(20216608, 'Tilted Try', '孤注差一掷', 'ツッパリーチ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己抽卡阶段通常抽卡时，把那1张卡给对方观看才能发动。那张卡回到卡组最下面，自己从卡组抽1张。 ②：自己因效果抽卡时，把那1张卡给对方观看才能发动。这张卡送去墓地，给人观看的卡回到卡组最下面，自己从卡组抽1张。'),
(77855162, 'Tilting Entrainment', '摆式特急 同律列车', '振子特急エントレインメント', 'Synchro Monster', 'Machine', 'EARTH', 8, 2800, 1600, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从自己的手卡·额外卡组（表侧）把1只4星以下的灵摆怪兽特殊召唤。 ②：这张卡或者自己的灵摆怪兽和对方怪兽进行战斗，那只对方怪兽没被破坏的伤害步骤结束时才能发动。那只对方怪兽破坏。'),
(53315891, 'Timaeus the Knight of Destiny', '合神龙 蒂迈欧', '合神竜ティマイオス', 'Fusion Monster', 'Warrior', 'LIGHT', 10, -1, -1, '「传说的骑士 克里底亚」＋「传说的骑士 赫谟」＋「传说的骑士 蒂迈欧」 把自己场上的上记卡送去墓地的场合才能特殊召唤（不需要「融合」）。 ①：这张卡不受其他卡的效果影响。 ②：这张卡进行战斗的伤害计算时才能发动。这张卡的攻击力·守备力变成和场上的怪兽的最高攻击力相同。 ③：这张卡被战斗破坏时才能发动。选自己的手卡·卡组·墓地3只「传说的骑士」怪兽无视召唤条件特殊召唤。'),
(3078380, 'Timaeus the United Dragon', '合体龙 提玛欧斯', '合体竜ティマイオス', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2800, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从自己的手卡·场上（表侧表示）把1只魔法师族怪兽或者1张有「黑魔术师」的卡名记述的魔法·陷阱卡送去墓地才能发动。这张卡特殊召唤。 ②：自己主要阶段才能发动。包含魔法师族怪兽的自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。'),
(85899505, 'Timaeus the United Magical Dragon', '合体魔龙 提玛欧斯', '合体魔竜ティマイオス', 'Fusion Monster', 'Dragon', 'LIGHT', 10, 2800, 1800, '「黑魔术师」或「黑魔术少女」＋龙族·魔法师族怪兽 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡特殊召唤时适用。直到下次的自己回合的结束时，这张卡不受其他卡的效果影响。 ②：这张卡进行战斗的伤害计算时才能发动。这张卡的攻击力上升双方的墓地·除外状态的魔法卡数量×100。 ③：对方回合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(90615639, 'Time Dimension Hole', '时间次元洞会馆', 'タイム・ディメンションホール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己卡组洗切。那之后，自己卡组最上面的卡翻开。翻开的卡是可以通常召唤的怪兽的场合，那只怪兽特殊召唤。不是的场合或者不能特殊召唤的场合，翻开的卡回到卡组最上面或最下面。'),
(15216188, 'Time Engine', '时间机械－时之引擎', '時の機械－タイム・エンジン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「金属化」卡使用。 ①：自己场上的怪兽被战斗或者对方的效果破坏的场合，以那之内的1只为对象才能发动。那只怪兽特殊召唤。这个效果把5星以上的机械族怪兽特殊召唤，自己的场上或墓地有这张卡以外的「金属化」陷阱卡存在的场合，可以再让以下效果适用。 ●对方场上的怪兽全部破坏。那之后，可以给与对方这个效果特殊召唤的怪兽的原本攻击力数值的伤害。'),
(73625877, 'Time Escaper', '时间逃逸者', 'タイム・エスケーパー', 'Effect Monster', 'Psychic', 'EARTH', 2, 500, 100, '把这张卡从手卡丢弃，选择自己场上表侧表示存在的1只念动力族怪兽发动。选择的怪兽直到下次的自己的准备阶段时从游戏中除外。这个效果在对方回合也能发动。'),
(80987696, 'Time Machine', '时间机械', '時の機械－タイム・マシーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己或者对方的怪兽1只被战斗破坏送去墓地时才能发动。在那只怪兽被破坏时的控制者场上以相同表示形式把那只怪兽特殊召唤。'),
(10960419, 'Time Magic Hammer', '时间魔术锤', 'タイムマジック・ハンマー', 'Fusion Monster', 'Spellcaster', 'LIGHT', 2, 500, 400, '这张卡在用「赫谟之爪」的效果把自己的手卡·场上的魔法师族怪兽送去墓地的场合才能特殊召唤。 ①：这张卡特殊召唤成功的场合，以这张卡以外的场上1只怪兽为对象发动。这张卡当作装备卡使用给那只怪兽装备。 ②：用这张卡的效果把这张卡装备的怪兽和对方怪兽进行战斗的伤害步骤开始时才能发动。掷1次骰子。那只对方怪兽直到和出现的数目相同次数的回合后的准备阶段为止除外。'),
(27107590, 'Time Maiden', '时械巫女', '時械巫女', 'Effect Monster', 'Fairy', 'LIGHT', 1, NULL, NULL, '①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：「时械神」怪兽上级召唤的场合，这张卡可以作为2只的数量解放。 ③：把这张卡解放才能发动。从卡组把1只攻击力0的「时械神」怪兽加入手卡。 ④：把墓地的这张卡除外才能发动。从卡组把1只攻击力0的「时械神」怪兽无视召唤条件特殊召唤。这个效果发动的回合，自己不能用这个效果以外把怪兽特殊召唤。'),
(94068856, 'Time Passage', '时间推移', 'タイムパッセージ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的1只名字带有「命运女郎」的怪兽的等级直到结束阶段时上升3星。'),
(1344018, 'Time Pendulumgraph', '时光的灵摆读阵', '時空のペンデュラムグラフ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，对方不能把自己场上的魔法师族怪兽作为陷阱卡的效果的对象。 ②：以自己的怪兽区域·灵摆区域1张「魔术师」灵摆怪兽卡和对方场上1张卡为对象才能发动。那些卡破坏。没能因这个效果把2张卡破坏的场合，可以把场上1张卡送去墓地。'),
(86346363, 'Time Reloader', '时间重绕机', 'タイム・リワインダー', 'Effect Monster', 'Machine', 'LIGHT', 8, 1200, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，场上的怪兽反转的场合才能发动。这张卡从手卡特殊召唤。那之后，场上1只表侧表示怪兽变成里侧守备表示。 ②：自己·对方的主要阶段，这张卡反转的场合，以自己墓地1只怪兽为对象才能发动。那只怪兽守备表示特殊召唤。那之后，场上1只表侧表示怪兽变成里侧守备表示。'),
(35316708, 'Time Seal', '刻之封印', '刻の封印', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：下次的对方抽卡阶段跳过。'),
(85808813, 'Time Stream', '时间流', 'タイム・ストリーム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「化石」融合怪兽为对象才能发动。那只怪兽解放，原本等级比那只怪兽高2星的1只「化石」融合怪兽当作「化石融合」的融合召唤从额外卡组特殊召唤。 ②：从自己墓地把这张卡和1只「化石」融合怪兽除外，以自己墓地1只「化石」融合怪兽为对象才能发动。那只怪兽特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(64730881, 'Time Thief Adjuster', '时潜怪盗・调校者', 'クロノダイバー・アジャスター', 'Effect Monster', 'Psychic', 'DARK', 4, 1200, 1800, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己对「时间潜行者·腕表调校员」以外的「时间潜行者」怪兽的召唤·特殊召唤成功的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「时间潜行者·腕表调校员」以外的1张「时间潜行者」卡送去墓地。'),
(82496097, 'Time Thief Bezel Ship', '时潜怪盗・表圈潜航艇', 'クロノダイバー・ベゼルシップ', 'Effect Monster', 'Machine', 'DARK', 4, 1000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放，以自己场上1只「时间潜行者」超量怪兽为对象才能发动。从对方墓地选1张卡在作为对象的怪兽下面重叠作为超量素材。这个效果在对方回合也能发动。 ②：这张卡在墓地存在的场合，把自己场上1个超量素材取除才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(74578720, 'Time Thief Chronocorder', '时潜怪盗・时间轴记录仪', 'クロノダイバー・タイムレコーダー', 'Effect Monster', 'Machine', 'DARK', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：对方战斗阶段把这张卡解放才能发动。这个回合只有1次，对方怪兽的攻击发生的对自己的战斗伤害由对方代受。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的超量怪兽因效果从场上离开的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。');